import numpy as np, pathlib, json

def transform(grid):
    a=np.array(grid)
    coords=np.argwhere(a==8)
    r0,c0=coords.min(axis=0); r1,c1=coords.max(axis=0)
    h,w=r1-r0+1,c1-c0+1
    # candidate by reflecting cells over the grid's 15.5 symmetry axes
    cand=[]
    # reflect across horizontal axis (rows)
    rr=[31-r for r in range(r0,r1+1)]
    if all(0<=r<a.shape[0] for r in rr):
        x=a[np.ix_(rr,range(c0,c1+1))]
        if not np.any(x==8): cand.append(x)
    # reflect across vertical axis (columns)
    cc=[31-c for c in range(c0,c1+1)]
    if all(0<=c<a.shape[1] for c in cc):
        x=a[np.ix_(range(r0,r1+1),cc)]
        if not np.any(x==8): cand.append(x)
    if cand:
        return cand[0].tolist()
    # Edge fallback: reflect across the visible grid's centerline.
    cc=[a.shape[1]-1-c for c in range(c0,c1+1)]
    return a[np.ix_(range(r0,r1+1),cc)].tolist()

